<script>
(() => {
const catalog=@json(config('actors.types'));
const unit=document.getElementById('unit_symbol'), types=document.getElementById('type_position');
if(unit){const previous=@json((string)old('type_position',''));function loadTypes(){types.replaceChildren();types.disabled=!unit.value;for(const [position,label] of Object.entries(catalog[unit.value]||{})){types.add(new Option(label,position));}if(previous && [...types.options].some(o=>o.value===previous)){types.value=previous;}}unit.addEventListener('change',loadTypes);loadTypes();}
const name=document.getElementById('actor_name'), identity=document.getElementById('identity_id'), fields=document.getElementById('new_identity_fields');
const known=@json($identities->map(fn($identity)=>['id'=>$identity->id,'name'=>$identity->display_name])->values());
if(identity){function selectIdentity(rename=true){const match=known.find(i=>String(i.id)===identity.value);if(match && rename){name.value=match.name;}if(fields){fields.hidden=!!identity.value;fields.querySelectorAll('input,select').forEach(field=>field.disabled=!!identity.value);}}identity.addEventListener('change',()=>{document.getElementById('new_identity').value=identity.value ? '0' : '1';selectIdentity();});selectIdentity(false);name.addEventListener('change',()=>{if(document.getElementById('new_identity').value==='1' || document.getElementById('identity_identifier_number')?.value.trim()){return;}const matches=known.filter(i=>i.name===name.value.trim());if(matches.length===1){identity.value=String(matches[0].id);selectIdentity();}});}
const personal=['first_name','second_name','paternal_surname','maternal_surname'].map(key=>document.getElementById('identity_'+key));
personal.forEach(field=>field?.addEventListener('input',()=>{const composed=personal.map(f=>f?.value.trim()||'').filter(Boolean).join(' ');if(composed){name.value=composed;}}));
const legal=document.getElementById('identity_legal_name');legal?.addEventListener('input',()=>{if(document.getElementById('identity_person_type')?.value==='legal' && legal.value.trim()){name.value=legal.value.trim();}});
})();
</script></x-admin-layout>
